1: #version 300 es
2: precision highp float;
3: 
4: uniform float u_aspectRatio;
5: uniform vec3 u_cameraPos;
6: uniform float u_fov;
7: uniform vec3 u_pointing;
8: 
9: uniform float u_time;
10: uniform float u_eps;
11: 
12: in vec2 uv;
13: 
14: layout (location = 0) out vec4 out_rayDir;
15: layout (location = 1) out vec4 out_normal;
16: layout (location = 2) out float out_depth;
17: 
18: vec3 refraction(vec3 ray, vec3 norm, float r) {
19:     norm = normalize(norm);
20:     ray = normalize(ray);
21: 
22:     float d = dot(norm, ray);
23:     float k = 1.0 - r*r*(1.0-d*d);
24: 
25:     if (k > 0.) {
26:         return r * ray - (r * d + sqrt(k)) * norm;
27:     }
28: 
29:     return ray - 2.0 * d * norm;
30: }
31: float opDisplacement(vec3 rayPos) {
32:     return sin(rayPos.x * 2.13) * sin(rayPos.y * 4.1) * sin(rayPos.z * 3.1);
33: }
34: vec3 opTwist(vec3 p, float k) {
35:     float c = cos(k*p.y);
36:     float s = sin(k*p.y);
37:     return vec3( mat2(c, -s, s, c) * p.xz, p.y);
38: }
39: 
40: float sdSphere(vec3 rayPos, vec3 spherePos, float r) {
41:     return length(rayPos - spherePos) - r;
42: }
43: float sdBox( vec3 rayPos, vec3 b ) {
44:     vec3 q = abs(rayPos) - b;
45:     return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
46: }
47: float sdCappedCylinder( vec3 p, float r, float h ) {
48:     vec2 d = abs(vec2(length(p.xy), p.z)) - vec2(r,h);
49:     return min(max(d.x,d.y),0.0) + length(max(d,0.0));
50: }
51: vec3 rotate(vec3 p, vec3 r) {
52:     vec3 s = sin(r);
53:     vec3 c = cos(r);
54:     // vec3 s = vec3(sin(r.x), sin(r.y), sin(r.z));
55:     // vec3 c = vec3(cos(r.x), cos(r.y), cos(r.z));
56: 
57:     return p * mat3(
58:         1., 0., 0.,
59:         0., c.x, -s.x,
60:         0., s.x, c.x
61:     ) * mat3(
62:         c.y, 0., s.y,
63:         0., 1., 0.,
64:         -s.y, 0., c.y
65:     ) * mat3(
66:         c.z, -s.z, 0.,
67:         s.z, c.z, 0.,
68:         0., 0., 1.
69:     );
70: }
71: 
72: float getDist(vec3 rayPos) {
73:     vec3 p = rotate(rayPos, vec3(sin(u_time), u_time*0.8, u_time*1.51) );
74: 
75:     return sdBox(
76:         p,
77:         vec3(2.0)
78:     ) - 0.5;
79: }
80: 
81: vec3 getNormal(vec3 rayPos) {
82:     const vec2 k = vec2(1, -1);
83: 
84:     vec3 norm = k.xyy * getDist(rayPos + k.xyy*u_eps) +
85:                 k.yxy * getDist(rayPos + k.yxy*u_eps) +
86:                 k.xxx * getDist(rayPos + k.xxx*u_eps) +
87:                 k.yyx * getDist(rayPos + k.yyx*u_eps);
88:                 
89:     return normalize(norm);
90: }
91: 
92: void main() {
93:     vec3 reference = normalize(u_pointing - u_cameraPos);
94: 
95:     vec3 horizontal = cross(reference, vec3(0.0, 0.0, 1.0)); // z vector is up
96:     vec3 vertical = cross(horizontal, reference);
97: 
98:     horizontal = normalize(horizontal) * tan(radians(u_fov) / 2.0);
99:     vertical = normalize(vertical) * tan(radians(u_fov) / 2.0) / u_aspectRatio;
100: 
101:     vec3 cameraRay = normalize(reference + (uv.x - 0.5) * 2.0 * horizontal + (uv.y - 0.5) * 2.0 * vertical);
102: 
103:     vec3 rayPos = u_cameraPos;
104:     vec3 rayDir = cameraRay;
105:     float totalDistance = 0.0;
106: 
107:     out_normal = vec4(0.0);
108:     out_depth  = 0;

